/*访问过快偶尔宕机，出错了会重试加载。
以下代码勿动！可在js中通过eval(String(source.bookSourceComment))
调用*/
var error = /503 Service Temporarily/;  
var maxRetries = 30; // 设置最大重试次数  
var retryCount = 0; // 初始化重试次数  

while (error.test(result) && retryCount < maxRetries) {  
    java.log("网站出错，重新加载");  
    cookie.removeCookie(baseUrl);  
    result = java.ajax(baseUrl);  
    retryCount++; // 每次循环后增加重试次数计数器  
}  

if (retryCount === maxRetries) {  
    java.log("重试次数已达到上限，放弃重试");  
} else {  
    result; // 如果循环结束且未达到上限，则返回结果  
}

ruleSearch.bookList:
.search_box p
<js>
result.toArray().slice(0, 3).map(el => {
	var url = String(el.select('a:eq(0)').attr('href')).replace(/^\//, 'https://www.9itan.com/');
	var J = org.jsoup.Jsoup.parse(java.ajax(url));
	var o = selector => String(J.select(selector).text());
	var og = selector => String(J.select('[property="og:' + selector + '"]').attr('content'));
	return {
		name: og('novel:book_name').replace(/(全文|小说|免费阅读|最新章节).*|[(（].*[）)]/g, ''),
		author: og('novel:author'),
		kind: og('novel:category') + ',' + og('novel:status').replace(/中|已/, ''),
		latest: og('novel:latest_chapter_name').replace(/^(正文|VIP章节|最新章节)?(\s+|_)|[\(（【].*[求更谢乐发推].*/g, '') + ' • ' + og('novel:update_time').replace(/(T|\s).*/, ' ').replace(/\//g, '-'),
		intro: og('description').replace(/.*(观看小说|简介)[:：]|各位书友.*/g, '').replace(/\s+/g, ''),
		cover: og('image'),
		url: url,
	};
}); 
</js>
